const sourceForStructure = (moduleId: string, category: string): string => {
  if (moduleId === 'skeletal-system') return /hand|carpal|tarsal|articular|radius|ulna|femur|tibia|fibula|pelvic|shoulder|humerus|forearm|foot|limb|rib landmarks/.test(category) ? SKELETAL_APPENDICULAR_SOURCE_ID : SKELETAL_AXIAL_SOURCE_ID;
  if (moduleId === 'nervous-system' && category === 'neural pathways') return NERVOUS_TISSUE_SOURCE_ID;
  return sourceForModule(moduleId);
};
const sourceForQuestion = (moduleId: string, structureId: string): string => moduleId === 'skeletal-system' && /carpal|foot|forearm|pelvis|leg|humer|radius|femur|rib/.test(structureId) ? SKELETAL_APPENDICULAR_SOURCE_ID : moduleId === 'nervous-system' && structureId === 'spinothalamic-tract' ? NERVOUS_TISSUE_SOURCE_ID : sourceForModule(moduleId);
const sourceForModule = (moduleId: string): string => ({
  'skeletal-system': SKELETAL_SOURCE_ID,
  'joints-ligaments': JOINTS_SOURCE_ID,
  'muscular-system': MUSCULAR_SOURCE_ID,
  'nervous-system': NERVOUS_SOURCE_ID,
}[moduleId] ?? OPENSTAX_SOURCE_ID);
