const makeStructures = (moduleId: string, rows: Array<[string, string, string, string[]]>): Structure[] => rows.map(([id, canonicalName, category, acceptedAliases]) => ({
  id, canonicalName, category, acceptedAliases, moduleId, sourceId: sourceForStructure(moduleId, category), sourcePage: null, examPriority: false, verificationStatus: 'verified',
}));
const sourceForLesson = (id: string): string => id.includes('joint') || id.includes('synovial') || id.includes('head-and-spine') || id.includes('upper-limb-joints') || id.includes('lower-limb-joints') ? JOINTS_SOURCE_ID : id.includes('muscle') || id.includes('axial') || id.includes('shoulder') || id.includes('arm-forearm') || id.includes('abdominal') || id.includes('hip-thigh') || id.includes('leg-and') ? MUSCULAR_SOURCE_ID : id.includes('neural-tracts') ? NERVOUS_TISSUE_SOURCE_ID : id.includes('brain') || id.includes('spinal') || id.includes('cranial-nerves') || id.includes('plexuses') || id.includes('ventricles') ? NERVOUS_SOURCE_ID : id.includes('cranial-fossae') || id.includes('regional-vertebrae') ? SKELETAL_AXIAL_SOURCE_ID : SKELETAL_APPENDICULAR_SOURCE_ID;
const makeLesson = (id: string, title: string, summary: string, structureIds: string[], recognitionCues: string[], landmarks: string[], relationships: string[], commonConfusions: string[], sourceId = sourceForLesson(id)): Lesson => ({
  id, title, summary, structureIds, recognitionCues, landmarks, relationships, commonConfusions, sourceIds: [sourceId],
});
const mc = (id: string, moduleId: string, structureId: string, prompt: string, answer: string | string[], options: string[], explanation: string, taskType: Question['taskType'] = 'multiple-choice'): Question => ({
  id, moduleId, structureIds: [structureId], taskType, prompt, answer, acceptedAliases: [], options, explanation, sourceId: sourceForQuestion(moduleId, structureId), sourcePage: null, examPriority: false, verificationStatus: 'verified',
});

